const BASE='https://manbow.nothing.sh/event/event.cgi?action=More_def&event=152&num=';
const rows=document.getElementById('rows'),q=document.getElementById('q'),count=document.getElementById('count');
let key='id',dir=1;
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function render(){
  const t=q.value.trim().toLowerCase();
  let list=DATA.filter(d=>!t||(d.id+' '+d.title+' '+d.artist+' '+d.file).toLowerCase().includes(t));
  list.sort((a,b)=>{
    const x=key==='id'?+a.id:String(a[key]||'').toLowerCase(), y=key==='id'?+b.id:String(b[key]||'').toLowerCase();
    return (x<y?-1:x>y?1:0)*dir || (+a.id-+b.id) || a.file.localeCompare(b.file);
  });
  rows.innerHTML=list.map(d=>`<tr><td class="id"><a href="${BASE}${+d.id}" target="_blank" rel="noopener">${d.id}</a></td><td>${esc(d.title)}</td><td>${esc(d.artist)}</td><td>${esc(d.file)}</td><td class="md5" title="클릭하면 복사">${d.md5}</td></tr>`).join('');
  count.textContent=list.length+' / '+DATA.length+' 채보';
}
document.querySelectorAll('th').forEach(th=>th.onclick=()=>{
  const k=th.dataset.k; dir=key===k?-dir:1; key=k;
  document.querySelectorAll('th').forEach(h=>h.textContent=h.textContent.replace(/ [▲▼]$/,''));
  th.textContent+=dir>0?' ▲':' ▼'; render();
});
rows.addEventListener('click',e=>{const c=e.target.closest('td.md5');if(c&&navigator.clipboard)navigator.clipboard.writeText(c.textContent)});
q.addEventListener('input',render);
render();
